class Shorthand:
    """A token that the parser replaces by a fixed list of tokens. For example,
    ``-q`` can stand for ``--log-level error --no-color``. The expansion is
    processed as if the user had typed it in place of the shorthand.

    :param name: The token to match, including its prefix, such as ``-q`` or
        ``--quiet``.
    :param expansion: The tokens that replace ``name``. They may be options,
        option values, positional tokens, or ``--``.
    :param help: Help text shown in the ``Shorthands`` section of the help page.
    :param hidden: Hide the shorthand from the help page.

    .. versionadded:: 8.6.0
    """

    name: str
    expansion: tuple[str, ...]
    help: str | None
    hidden: bool

    def __init__(
        self,
        name: str,
        expansion: cabc.Sequence[str],
        help: str | None = None,
        hidden: bool = False,
    ) -> None:
        if not _is_valid_shorthand_name(name):
            raise ValueError(f"Invalid shorthand name {name!r}.")

        if isinstance(expansion, str):
            raise TypeError(
                "Shorthand expansion must be a sequence of strings, not a single string."
            )

        tokens = tuple(expansion)

        if not all(isinstance(token, str) for token in tokens):
            raise TypeError("Shorthand expansion tokens must be strings.")

        if not tokens:
            raise ValueError(f"Shorthand {name!r} must expand to at least one token.")

        self.name = name
        self.expansion = tokens
        self.help = help
        self.hidden = hidden

    def to_info_dict(self) -> dict[str, t.Any]:
        return {
            "name": self.name,
            "expansion": list(self.expansion),
            "help": self.help,
            "hidden": self.hidden,
        }

    def __repr__(self) -> str:
        return f"<{self.__class__.__name__} {self.name}>"


