def shorthand(
    name: str, *expansion: str, help: str | None = None, hidden: bool = False
) -> t.Callable[[FC], FC]:
    """Attaches a shorthand to the command. The shorthand is validated when this
    function is called. A shorthand token is replaced by its ``expansion`` while the
    command is parsed.

    :param name: The token to match, including its prefix, such as ``-q``.
    :param expansion: The tokens that replace ``name``.
    :param help: Help text shown in the ``Shorthands`` section of the help page.
    :param hidden: Hide the shorthand from the help page.

    .. versionadded:: 8.6.0
    """
    sh = Shorthand(name, expansion, help=help, hidden=hidden)

    def decorator(f: FC) -> FC:
        _shorthand_memo(f, sh)
        return f

    return decorator


